/**
 * Read-only exploration of aggregate facts generated by the audited Python run.
 * This module does not load source logs, infer learner identities or estimate
 * assistance outside the source capture boundary.
 */
import CROSS_SOURCE_ANALYSIS from './cross-source-analysis-data.mjs';

function validCount(value) {
  return Number.isSafeInteger(value) && value >= 0;
}

/** Recompute a descriptive count from selected source strata, never a rate. */
export function summarizeCrossSource(data, selectedSourceIds = null) {
  if (data?.schema_version !== '1.0.0' ||
      data?.metric?.id !== 'recorded_help_request_observations' ||
      !Array.isArray(data.sources) || !data.sources.length) {
    throw new TypeError('Expected a supported aggregate assistance analysis.');
  }
  const known = new Set();
  for (const source of data.sources) {
    if (typeof source?.source_id !== 'string' || !source.source_id || known.has(source.source_id) ||
        typeof source.label !== 'string' || !source.label ||
        !validCount(source.assistance_request_observations) || source.synthetic === true ||
        (source.help_request_subtypes !== undefined && (!Array.isArray(source.help_request_subtypes) ||
          source.help_request_subtypes.some(subtype => typeof subtype?.label !== 'string' || !validCount(subtype.count))))) {
      throw new TypeError('Expected distinct real-source strata with non-negative integer observation counts.');
    }
    known.add(source.source_id);
  }
  if (selectedSourceIds !== null && !Array.isArray(selectedSourceIds)) {
    throw new TypeError('Source selection must be an array of source identifiers.');
  }
  const selected = selectedSourceIds === null ? known : new Set(selectedSourceIds);
  if ([...selected].some(id => !known.has(id))) throw new TypeError('Unknown source identifier.');
  const sources = data.sources.filter(source => selected.has(source.source_id));
  let total = 0;
  const cumulative = sources.map(source => {
    total += source.assistance_request_observations;
    if (!Number.isSafeInteger(total)) throw new RangeError('Observation sum exceeds safe integer precision.');
    return {source_id:source.source_id, added_count:source.assistance_request_observations, cumulative_count:total};
  });
  return {
    metric_id:data.metric.id,
    source_count:sources.length,
    assistance_request_observations:total,
    sources,
    cumulative,
    // An observed record count supplies none of these quantities.
    actual_request_total:null,
    unique_cross_source_learners:null,
    request_rate:null,
    request_to_display_rate:null,
    learning_effect:null
  };
}

const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number = value => Number(value).toLocaleString('en-US');

function sourceURL(source) {
  try {
    const url = new URL(source.source_url);
    return url.protocol === 'https:' ? url.href : null;
  } catch { return null; }
}

export function mountCrossSourceAnalysis(document, data = CROSS_SOURCE_ANALYSIS) {
  const section = document.getElementById('cross-source-analysis');
  if (!section) return;
  // Validate packaged data before displaying any empirical count.
  summarizeCrossSource(data);
  const picker = document.getElementById('cross-source-picker');
  const selected = new Set(data.sources.map(source => source.source_id));
  picker.innerHTML = data.sources.map((source, index) => `<label class="cross-source-choice"><input type="checkbox" data-cross-source="${index}" checked><span><strong>${esc(source.label)}</strong><small>${number(source.assistance_request_observations)} recorded request observations</small></span></label>`).join('');

  const render = () => {
    const result = summarizeCrossSource(data, [...selected]);
    document.getElementById('cross-source-total').textContent = number(result.assistance_request_observations);
    document.getElementById('cross-source-selection').textContent = `${result.source_count} selected ${result.source_count === 1 ? 'source' : 'sources'} · recorded occurrences only`;
    const max = Math.max(1, ...result.sources.map(source => source.assistance_request_observations));
    const contribution = document.getElementById('cross-source-contributions');
    contribution.innerHTML = result.sources.length ? result.sources.map((source, index) => `<div class="cross-contribution"><div class="cross-contribution-label"><strong>${esc(source.label)}</strong><span>${number(source.assistance_request_observations)}<small> observed records</small></span></div><div class="cross-contribution-track" aria-hidden="true"><span class="cross-contribution-fill cross-source-color-${index % 3}" data-cross-bar="${index}"></span></div><p>Cumulative selected count: <strong>${number(result.cumulative[index].cumulative_count)}</strong></p></div>`).join('') : '<p class="cross-empty">No source selected. The selected record count is zero; actual assistance remains unknown.</p>';
    for (const [index, source] of result.sources.entries()) {
      contribution.querySelector(`[data-cross-bar="${index}"]`).style.width = `${100 * source.assistance_request_observations / max}%`;
    }
    document.getElementById('cross-source-table').innerHTML = result.sources.map(source => {
      const url = sourceURL(source);
      const label = url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(source.label)} ↗</a>` : esc(source.label);
      const subtypes = Array.isArray(source.help_request_subtypes) ? source.help_request_subtypes.map(subtype => `${esc(subtype.label)}: ${number(subtype.count)}`).join('<br>') : 'See mapping in the download.';
      return `<tr><th scope="row">${label}<small>${esc(source.release || '')}</small>${validCount(source.native_input_count) ? `<small>${number(source.native_input_count)} native records scanned</small>` : ''}</th><td>${subtypes}</td><td class="mono">${number(source.assistance_request_observations)}</td><td>Unknown<small>${esc(source.capture_coverage?.reason || 'Complete capture is not established.')}</small></td></tr>`;
    }).join('') || '<tr><td colspan="4">Select a source to inspect its contribution.</td></tr>';
    document.getElementById('cross-source-query-result').textContent = JSON.stringify({metric_id:result.metric_id, by_source:result.sources.map(source => ({source_id:source.source_id, recorded_request_observations:source.assistance_request_observations})), selected_recorded_observations:result.assistance_request_observations, actual_request_total:null, request_rate:null, request_to_display_rate:null, unique_cross_source_learners:null, learning_effect:null}, null, 2);
  };
  picker.addEventListener('change', event => {
    const input = event.target;
    const index = input?.getAttribute?.('data-cross-source');
    if (index === null || index === undefined) return;
    const source = data.sources[Number(index)];
    if (!source) return;
    if (input.checked) selected.add(source.source_id); else selected.delete(source.source_id);
    render();
  });
  document.getElementById('cross-source-all').addEventListener('click', () => {
    for (const source of data.sources) selected.add(source.source_id);
    for (const input of picker.querySelectorAll('input')) input.checked = true;
    render();
  });
  document.getElementById('cross-source-summary').textContent = JSON.stringify(data, null, 2);
  document.getElementById('cross-source-definition').textContent = data.metric.common_definition || data.metric.definition || data.metric.description || data.metric.unit;
  render();
}

if (typeof document !== 'undefined') {
  try { mountCrossSourceAnalysis(document); }
  catch {
    const status = document.getElementById('cross-source-selection');
    if (status) status.textContent = 'Packaged analysis unavailable. No empirical counts are shown.';
  }
}
